('rooftop-lantern', 'Rooftop Lantern (Sample)', 'Colombo 3', 'Restaurant', 2500, 4000, array['Date night', 'Romantic', 'Quiet']::text[], 'Small rooftop with fairy lights and a sea breeze. Seafood and grill menu. Ask for the corner table at sunset.', '', '[{"item":"Grilled seer fish","price":3200},{"item":"Prawn pasta","price":2900},{"item":"Mocktail","price":950}]'::jsonb, '2026-11-01', '17:00', '23:00', 6.9135, 79.8491, '0771234567', '94771234567', '#C2410C', true, false, true, 'instant', 6, 6, 30, '18:00', '21:30', 2),
('kandelia-tea-house', 'Kandelia Tea House (Sample)', 'Colombo 7', 'Café', 1500, 3000, array['Romantic', 'Cozy café', 'Quiet', 'Date night']::text[], 'Old bungalow turned tea house with a quiet garden. Estate tea flights and high tea on weekends.', '', '[{"item":"Estate tea flight","price":1800},{"item":"High tea for two","price":5500},{"item":"Love cake","price":650}]'::jsonb, '2026-11-01', '10:00', '21:00', 6.9034, 79.8688, '0772345678', '94772345678', '#6D28D9', true, false, true, 'request', 4, 6, 30, '15:00', '20:00', 2),
('galle-face-walk', 'Galle Face Sunset Walk', 'Colombo 3', 'Activity', 0, 300, array['Outdoor', 'Romantic', 'Budget', 'Family', 'Date night']::text[], 'Free seaside walk with kites, street food carts and the best sunset in the city. Go 30 minutes before sunset.', '', '[]'::jsonb, '2026-11-01', '05:00', '23:00', 6.9271, 79.845, '', '', '#0E7490', true, false, false, 'instant', 4, 6, 30, '18:00', '21:30', 2),
('isso-wade-cart', 'Green Umbrella Isso Wade (Sample)', 'Colombo 3', 'Street Food', 300, 700, array['Street food', 'Budget', 'Outdoor', 'With friends']::text[], 'The green-umbrella cart on the south end of Galle Face. Crispy isso wade, made in front of you.', '', '[{"item":"Isso wade (3)","price":400},{"item":"Parippu wade","price":100},{"item":"Mango achcharu","price":250}]'::jsonb, '2026-11-01', '15:00', '23:00', 6.9231, 79.8449, '', '', '#B91C1C', false, true, false, 'instant', 4, 6, 30, '18:00', '21:30', 2),
